from capstone.x86 import X86_OP_MEM,X86_REG_RCX
cs.detail=True
# Bounded new supply accessor search. Do not execute any of these candidates.
candidates=[]
for s,e,u in fns:
 if not 0xf40000<=s<0xf4d000 or e-s>192:continue
 ins=list(cs.disasm(p.read_rva(s,e-s),s));reads=[f'{i.address:x} {i.mnemonic} {i.op_str}'for i in ins if any(o.type==X86_OP_MEM and o.mem.base==X86_REG_RCX and 0x20<=o.mem.disp<=0xa0 for o in i.operands)]
 if reads:
  lines=clip(s);candidates.append({'fn':hex(s),'size':e-s,'field_access':reads,'fixed_literal_100000':any('0x186a0'in x for x in lines),'has_division':any('div'in i.mnemonic for i in ins)})
(R/'research/t200_supply_accessor_candidates.json').write_text(json.dumps(candidates,indent=2),encoding='utf-8');print('SUPPLY_ACCESSORS',json.dumps(candidates,indent=2))
